import json
from pathlib import Path
S=Path(__file__).resolve().parents[1];cat=json.loads((S/'data/catalog.json').read_text(encoding='utf8'));p=S/'analysis/SuperChina.json';out=json.loads(p.read_text(encoding='utf8')) if p.exists() else {}
base={'滑價':'以價格點數扣每側每口；報表FIFO配對完成一口扣兩側，未平倉不作即時市價DD。不是tick數或%。','開始交易時間':'共用一般報價在此以前標session=1；是否仍出入取決本策略是否讀session，本策略忽略此旗標。','最後交易時間':'共用一般報價在此以後標session=1，並非強制平倉；本策略未讀此旗標。','進場調整點':'本策略進出邏輯沒有使用此繼承欄位。'}
common='一般報價先受商品報價時窗與全域間隔篩選。內部交易按qe.open記錄、按策略淨部位差彙總交給帳戶層並乘全域下單口數；FastMode不送帳戶單。模擬記錄不等於交易所成交。'
cost='同一策略實例在本次回測內的子部位共用FIFO逐口配對並扣雙邊滑價，可能跨子策略相抵；MaxDrawdown只隨完成配對的損益更新，沒有未平部位市價估值。'
def add(name,summary,family,entry,exit,mechanics,caveats,notes):
 iid='SuperChina/Stg'+name;n=base|notes;out[iid]={'summary':summary,'family':family,'entry':entry,'exit':exit,'mechanics':mechanics,'caveats':caveats,'parameterNotes':{p['name']:n[p['name']] for p in next(i for i in cat['items'] if i['id']==iid)['parameters']}}
add('Quote','只接收報價的空策略骨架，沒有進場、出場或建立交易子項的規則。','報價與工具',['交易分派覆寫為空；新增策略回傳null，不會因價格自動建倉。'],['沒有本地策略平倉規則。'],['類別有編入專案，但StgList建立語句被註解，因此標記未在清單中。'],['不能把報價工具當成已實作的交易策略，也不能從名稱推導交易訊號。'],{})
add('HDM','用期貨對同日最新大盤指數的正逆價差反向交易：期貨過高放空，過低做多，可選回中線平倉或持到反向外帶。','價差與配對',['記錄最新大盤指數open；只在同日指數存在且其時間不是09:00分鐘時處理期貨，未檢查與期貨相差幾秒。','期貨open>指數open+距離做空一口，<指數open−距離做多一口；帶內保持或依中線原則平倉。反向穿越外帶會直接用兩口由多轉空或由空轉多。'],['遇中線出場時，多單在價格>=指數、空單在價格<=指數後於帶內平倉；在原先有利的同側帶內仍保留。遇中線不出場則等另一外帶反手。','沒有額外固定停損、停利或日末自動平倉。'],[common,cost,'只建立並使用第一個子策略；多空比在建立時複製，中線原則則讀母策略目前設定。'],['未限制指數報價新鮮度，可用當日較舊指數；多空門檻和成交都以open為主。','忽略一般報價session=1的只停損標記，交易時間外若仍在商品報價時窗可能照樣建倉。'],{'多空比':'以最新指數價計%或直接點數，形成上下價差帶；嚴格超越才進場，等於邊界不算外帶。','中線原則':'遇中線不出場在帶內保留；遇中線出場只在持倉穿過指數中線的那側平倉，不是在進入外帶內側立刻平。'})
add('BD26','以最新基準上下固定間隔順勢進場與加碼，加滿後沿價格格距推動退出線；回撤一格則整組停止。','突破與加碼',['沒有啟動中子項時以當筆open建一條空手基準，下一筆才檢查；上破目標多−進場調整點買一口，下破目標空+進場調整點賣一口。','有利方向再走一格且未滿次數時送出1+(已加碼次數+1)×加碼口數作為新增量，並重設上下目標。這是實際增加的口數，不是加碼後總量。'],['有倉朝不利方向觸及另一邊目標，以當筆open全部停止；已用完加碼次數後每再走一格只移基準與上下目標，不立即停利。','開啟當沖時HHmm>=當沖平倉時間全部停止，當日時刻之後直接略過；下一個較早時刻可重新放行。'],[common,cost,'價格基準設定沒有被新增策略使用；每次新建基準取實際open。上一筆仍啟動而這筆被停止時，本根不補新線，下一筆才可重建。'],['加碼新增量隨次數遞增，總持倉比固定每次加碼口數更大；沒有總部位限制。','單日最大損失只有欄位，沒有實作判斷。Clear也未重設此類私有日截止時刻；時間放行依TimeOfDay而非交易日期。'],{'價格基準':'未被實際建線或交易流程讀取；基準一律用當下open。','價格間隔':'基準上下各隔此點數，入場、加碼或推線後從實際open重設。','加碼口數':'第k次加碼實送1+k×此值口，並累加到既有部位，並非只新增此值。','可加碼次數':'有利方向最多觸發幾次加碼；之後仍可按格移退出線。','啟動當沖策略':'到當沖平倉時間強制平倉並以當日時刻封鎖後續處理。','當沖平倉時間':'HHmm，第一筆>=時執行全部平倉，沒有缺分鐘補成交的限價。','單日最大損失':'尚未實作；不會因當日損益達此值退出。','進場調整點':'只調空手進場：多目標減此點數、空目標加此點數，可提早觸發；持倉退出與加碼不調。'})
add('BD28','開盤相對前次正常時段最後open跳空達門檻，採反向一口交易；不利延伸一個跳空幅度停損，有利時可隔夜到下一開盤。','跳空反向',['時刻回退後第一筆HHmm>=開始交易時間，先退出舊隔夜倉，再以此open減先前session=0最後open計跳空。','向上跳空>=門檻做空；向下<=負門檻做多。沒有先前正常報價時不建立，第一日無法憑空計跳空。'],['上跳做空的停損線為開盤再加原跳空幅度；下跳做多為開盤再加負跳空幅度。後續open到線整組停止。','第一筆>=當沖平倉時間時，不留夜則全部停；留夜則只保留相對入場基準已有嚴格正價差者，等於零也退出。之後當日不再查停損，下一次開盤一律退出隔夜倉。','結算覆寫成全部平倉，並把當沖狀態設為結束，不採一般換月重開。'],[common,cost,'昨收變數實為最後一次session=0的qe.open，並非前一根close；整個日界靠TimeOfDay回退，不按商品TradeDate。'],['截止留倉用未扣成本價差決定，並非報表淨獲利；隔夜後當晚未繼續價格風控。','每根外層按子項數循環，但其中開盤/HN函式又掃全體；舊子項多時可能重複留下停止訊息。'],{'開始交易時間':'日內時刻回退後第一筆HHmm>=此值才算開盤，退出舊倉並測新跳空；也影響共用session旗標。','最後交易時間':'僅共用標記session=1，不直接強平；正常session=0最後open供下次跳空比較。','跳空進場點數':'用當次開盤open相對上次正常時段最後open計點數；>=做空，<=負值做多。','HoldNight':'當沖截止僅保留入場至當筆有嚴格有利價差的持倉，下一開盤退出；不扣滑價判斷。','當沖平倉時間':'HHmm，到時第一次處理留倉／平倉，以後當日略過一般策略與保護。'})
add('MA','以日收盤均線為中心，先等價格回到均線再突破外帶順勢交易；跌回均線、反向突破、逐筆跳價或移停可退出。','均線突破',['需先由使用者／環境新增MA子項；主迴圈不自動建立。相鄰報價換日期時才以全域日收盤清單最後N筆算均線，資料不足不更新。','初始價格在均線上方先等回落均線，下方先等反彈均線；就緒後突破上帶買一口、下帶空一口。等待回均線的那根若已越另一外帶，可直接反向入場。'],['先檢查既有移停線，再檢查回到均線退出；同根越過相反外帶可直接反手。未回均線時再比較本筆open與上一筆open的不利跳價門檻。','有利走到進場價±啟動距離後，以當筆open減／加拉回距離建立只往有利方向移動的線。退出後重設等待回均線狀態；沒有資料末筆強平。'],[common,cost,'執行子策略先把OHLC全部覆成open，故沒有真正當根高低價成交。換倉移保護價、不移均線與外帶，並清除上一報價以略過一次跳空檢查。'],['名為昨日收盤價的欄位每次更新為本筆open，所以跳空出場實際逐報價比較，並不限於隔日第一根。','若重用物件，Clear保留啟動子項但不重設last_qe；均線取全域清單尾端，正確資料截止依執行環境維護，策略本身沒有按本根日期過濾。','本版不讀session只停損旗標，開始／最後交易時間不直接限制入場。'],{'MA長度':'每個子項建立時複製的日收盤平均筆數；日界更新使用清單尾N筆，0或資料不足回0不更新。','多空進場p':'均線加減的外帶距離，支持%或點數，按商品最小升降單位四捨五入。','跳空出場p':'對前一報價open的不利跳變距離，%以目前open換算，不只檢查隔日開盤。','啟動移停p':'從實際入場open換算有利距離，%或點數；到價才開始建移停線。','移停拉回p':'當筆有利open減／加的追蹤距離，%以該筆open換算，線僅往有利方向更新。'})
p.write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf8');print('Wrote 5 SuperChina explanations')
